import math
mem_pts=[]
mem_corners=[]
dsm=0.0
mode='rev'
fwd_t=0.0
last_print=-10

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def clamp(x,lo,hi):
    return max(lo,min(hi,x))

def control(obs):
    global mem_pts,mem_corners,dsm,mode,fwd_t,last_print
    rig=obs['rig']; H=rig['hitch']; R=rig['trailer_rear']
    h=obs.get('hitch_deg',0.0) or 0.0
    t=obs.get('t',0.0)
    look=rig.get('screen_gaze_deg')
    if look is None: look=-65
    views=obs.get('views') or {}
    pts=[]; corners=[]
    for name,v in views.items():
        try:
            ox,oy=v['origin']
            for w in v.get('walls',[]) or []:
                b,d=w[0],w[1]
                pts.append((ox+d*math.cos(math.radians(b)),oy+d*math.sin(math.radians(b))))
            for c in v.get('target_corners',[]) or []:
                b,d=c[0],c[1]
                corners.append((ox+d*math.cos(math.radians(b)),oy+d*math.sin(math.radians(b))))
        except Exception:
            pass
    if views:
        mem_pts=pts
        mem_corners=corners
    pts=mem_pts; corners=mem_corners
    thb=math.degrees(math.atan2(R[1]-H[1],R[0]-H[0]))
    best=None; bestd=0.0
    for dd in range(-60,61,5):
        a=math.radians(thb+dd); ux,uy=math.cos(a),math.sin(a)
        free=9.0
        for (px,py) in pts:
            qx,qy=px-R[0],py-R[1]
            al=qx*ux+qy*uy; lat=qx*uy-qy*ux
            if al>0 and abs(lat)<1.0 and al<free: free=al
        side=2.0
        lim=min(free,4.0)
        for (px,py) in pts:
            qx,qy=px-R[0],py-R[1]
            al=qx*ux+qy*uy; lat=qx*uy-qy*ux
            if -1.0<al<lim and abs(lat)<side: side=abs(lat)
        sc=min(free,8.0)+3.0*min(side,2.0)-0.02*abs(dd)
        if best is None or sc>best:
            best=sc; bestd=dd
    delta=float(bestd) if pts else 0.0
    if len(corners)>=2:
        cx=sum(c[0] for c in corners)/len(corners); cy=sum(c[1] for c in corners)/len(corners)
        dc=wrap(math.degrees(math.atan2(cy-R[1],cx-R[0]))-thb)
        delta=0.3*delta+0.7*clamp(dc,-45,45)
    dsm=dsm+0.3*(delta-dsm)
    rem=9.0
    try: rem=obs['progress']['remaining']
    except Exception: pass
    if mode=='rev' and abs(h)>40:
        mode='fwd'; fwd_t=t
    if mode=='fwd':
        if abs(h)<8 and t-fwd_t>1.5:
            mode='rev'
        else:
            return (0.0,1.0,look)
    hd=clamp(0.6*dsm,-28,28)
    steer=0.75*hd+2.0*(h-hd)
    steer=clamp(steer,-34,34)
    sp=-1.0 if rem>4 else -0.7
    if t-last_print>3:
        last_print=t
        print('t%.1f h%.1f hd%.1f d%.1f st%.1f np%d nc%d rem%.1f'%(t,h,hd,dsm,steer,len(pts),len(corners),rem))
    return (steer,sp,look)

