    steer=clamp(steer,-30,30)
    last_steer=steer
    sp=-0.9 if rem>4 else -0.6
    if t-last_print>2:
        last_print=t
        print('t%.1f %s %s h%.1f hd%.1f bd%d rep%.0f st%.1f np%d nc%d rem%.1f'%(t,mode,st,h,hd,bestd,rep,steer,len(pts),len(corners),rem))
    return (steer,sp,look)

