import math
X=0.0;Y=0.0;TH=0.0
state='fwd';tick=0;stopped=False;woke=False;fx=0.0;fy=0.0
PATH=[(10.0,1.2),(-4.24,1.2),(-12.42,13.8)]

def clamp(v,a,b):
    return max(a,min(b,v))

def nearest(px,py):
    best=(1e9,0.0);acc=0.0
    for i in range(len(PATH)-1):
        x0,y0=PATH[i];x1,y1=PATH[i+1]
        dx=x1-x0;dy=y1-y0;L=math.hypot(dx,dy)
        t=((px-x0)*dx+(py-y0)*dy)/(L*L)
        t=clamp(t,0.0,1.0)
        d=math.hypot(px-x0-t*dx,py-y0-t*dy)
        if d<best[0]: best=(d,acc+t*L)
        acc+=L
    return best

def point_at(s):
    acc=0.0
    for i in range(len(PATH)-1):
        x0,y0=PATH[i];x1,y1=PATH[i+1]
        L=math.hypot(x1-x0,y1-y0)
        if s<=acc+L or i==len(PATH)-2:
            t=(s-acc)/L
            return (x0+t*(x1-x0),y0+t*(y1-y0))
        acc+=L

def clr(obs,vm,tm):
    rig=obs['rig'];rx,ry=rig['trailer_rear'];hx,hy=rig['hitch']
    L=math.hypot(hx-rx,hy-ry) or 1.0
    ux=(hx-rx)/L;uy=(hy-ry)/L
    for name,vw in (obs.get('views') or {}).items():
        try:
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]):
                if d>8: continue
                br=math.radians(b)
                px=ox+d*math.cos(br);py=oy+d*math.sin(br)
                dv=math.hypot(max(-0.9-px,0.0,px-3.0),max(abs(py)-1.15,0.0))
                qa=(px-rx)*ux+(py-ry)*uy;qb=-(px-rx)*uy+(py-ry)*ux
                dtr=math.hypot(max(-qa,0.0,qa-4.6),max(abs(qb)-1.2,0.0))
                if dv<vm or dtr<tm:
                    return '%s b%.0f d%.2f p(%.2f,%.2f) dv%.2f dt%.2f'%(name,b,d,px,py,dv,dtr)
        except Exception:
            pass
    return None

def control(obs):
    global X,Y,TH,state,tick,stopped,woke,fx,fy
    tick+=1
    t=obs['t']
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps']
    d=math.radians(obs['steer_deg'])
    TH+=v*math.tan(d)/2.5*dt
    X+=v*math.cos(TH)*dt;Y+=v*math.sin(TH)*dt
    hitch=obs['hitch_deg']
    status=obs['status']
    if stopped:
        return (obs['steer_deg'],0.0,obs['head']['gaze_deg'])
    if state=='fwd':
        gaze=0.0
        Ld=3.5
        al=math.atan2(1.0-Y,Ld)-TH
        st=math.degrees(math.atan(2*2.5*math.sin(al)/Ld))
        lim=15.0 if X<1.2 else 25.0
        st=clamp(st,-lim,lim)
        if X>1.2:
            c=clr(obs,0.08,0.12)
            if c:
                stopped=True;print('STOP fwd',c,'X%.1f Y%.1f th%.0f h%.1f'%(X,Y,math.degrees(TH),hitch));wake('rail close fwd')
                return (st,0.0,gaze)
        if tick%15==0: print('F t%.1f X%.1f Y%.2f th%.1f h%.1f st%.0f'%(t,X,Y,math.degrees(TH),hitch,st))
        if X>4.5:
            state='rev';print('to rev X%.1f Y%.2f th%.1f h%.1f'%(X,Y,math.degrees(TH),hitch))
        return (st,0.8,gaze)
    if state=='rec':
        st=clamp(-1.2*hitch,-45,45)
        if math.hypot(X-fx,Y-fy)>2.0 and abs(hitch)<15: state='rev'
        return (st,0.8,0.0)
    if status=='JACKKNIFED' or abs(hitch)>50:
        state='rec';fx=X;fy=Y;print('rec t%.1f h%.1f'%(t,hitch))
        return (clamp(-1.2*hitch,-45,45),0.0,0.0)
    gaze=170.0 if (t%5.0)<3.0 else -64.0
    rig=obs['rig']
    rx,ry=rig['trailer_rear'];hx,hy=rig['hitch']
    L=math.hypot(hx-rx,hy-ry) or 1.0
    ax=rx+1.4*(hx-rx)/L;ay=ry+1.4*(hy-ry)/L
    c=math.cos(TH);s=math.sin(TH)
    AX=X+ax*c-ay*s;AY=Y+ax*s+ay*c
    beta=TH+math.radians(rig['trailer_heading_deg'])+math.pi
    cross,sp_=nearest(AX,AY)
    PX,PY=point_at(sp_+4.5)
    dx=PX-AX;dy=PY-AY;D=math.hypot(dx,dy)
    al=math.atan2(dy,dx)-beta
    al=math.atan2(math.sin(al),math.cos(al))
    k=2*math.sin(al)/max(D,0.5)
    phides=clamp(-math.degrees(math.asin(clamp(k*3.6,-0.7,0.7))),-32,32)
    pr=math.radians(phides)
    ff=math.degrees(math.atan(2.5*math.sin(pr)/(3.6+1.3*math.cos(pr))))
    steer=clamp(ff+2.0*(hitch-phides),-45,45)
    sp=0.6
    if abs(hitch-phides)>10: sp=0.4
    if v<-0.05:
        cc=clr(obs,0.1,0.2)
        if cc:
            stopped=True;print('STOP rev',cc,'A(%.1f,%.1f) s%.1f h%.1f'%(AX,AY,sp_,hitch));wake('rail close rev')
            return (steer,0.0,gaze)
    if tick%20==0:
        print('R t%.1f s%.1f x%.2f h%.1f phd%.1f A(%.1f,%.1f) X%.1f Y%.1f th%.0f'%(t,sp_,cross,hitch,phides,AX,AY,X,Y,math.degrees(TH)))
    if sp_>21.0 and not woke:
        woke=True;wake('7 m into diagonal, replan')
    return (steer,-sp,gaze)

