        if dg: nd+=1
        else: nd=0
        if nd>=2:
            state='hold';print('STOP rev',dg,'A(%.1f,%.1f) h%.1f X%.1f Y%.1f th%.0f s%.1f'%(AX,AY,hitch,X,Y,math.degrees(TH),s));wake('rail close rev')
