import math
X=0.0;Y=0.0;PSI=0.0
pts={}
phase='rev'
woken=set()
last_touch=0
def cl(a,lo,hi):
    return max(lo,min(hi,a))
def wk(k,msg):
    if k not in woken:
        woken.add(k)
        try:
            wake(msg)
        except Exception:
            pass
def control(obs):
    global X,Y,PSI,phase,last_touch
    t=obs['t']; dt=obs.get('dt',0.1) or 0.1
    m=obs['motion']; v=m['v_mps']; st=obs['steer_deg']
    X+=v*math.cos(PSI)*dt; Y+=v*math.sin(PSI)*dt
    PSI+=v*math.tan(math.radians(st))/3.9*dt
    c=math.cos(PSI); s=math.sin(PSI)
    for name,vw in (obs.get('views') or {}).items():
        if not vw: continue
        ox,oy=vw['origin']
        for w in vw.get('walls',[]):
            b,d=w[0],w[1]
            if d>18: continue
            px=ox+d*math.cos(math.radians(b)); py=oy+d*math.sin(math.radians(b))
            wx=X+c*px-s*py; wy=Y+s*px+c*py
            pts[(round(wx*3),round(wy*3))]=(wx,wy)
    rig=obs['rig']; R=rig['trailer_rear']; th=rig['trailer_heading_deg']; hitch=obs['hitch_deg']
    touches=obs['counters']['touches']
    if touches>last_touch:
        last_touch=touches
        wk('touch%d'%touches,'touched rail')
    loc=[]
    for (wx,wy) in pts.values():
        dx=wx-X; dy=wy-Y
        vx=c*dx+s*dy; vy=-s*dx+c*dy
        if abs(vx-R[0])<24 and abs(vy-R[1])<24:
            loc.append((vx-R[0],vy-R[1]))
    back=180.0+th
    hw=1.45
    res=[]
    for phi in range(-70,71,5):
        a=math.radians(back-phi); ux=math.cos(a); uy=math.sin(a)
        f=20.0
        for (px,py) in loc:
            al=px*ux+py*uy
            if al>0 and al<f:
                lat=ux*py-uy*px
                if abs(lat)<hw: f=al
        res.append((phi,f))
    f0=[f for p,f in res if p==0][0]
    best=max(f-0.02*abs(p) for p,f in res)
    sw=0.0; sp=0.0
    for p,f in res:
        sc=f-0.02*abs(p)
        if sc>=0.85*best:
            sw+=f; sp+=f*p
    phid=sp/sw if sw>0 else 0.0
    a=math.radians(back); ux=math.cos(a); uy=math.sin(a)
    cL=9.0; cR=9.0
    for (px,py) in loc:
        al=px*ux+py*uy
        if -13<al<1.0:
            lat=ux*py-uy*px
            if 0<lat<4: cL=min(cL,lat)
            elif -4<lat<=0: cR=min(cR,-lat)
    cent=0.0
    if cL<4 and cR<4: cent=cl(4.0*(cL-cR),-10,10)
    elif cL<1.0: cent=-4.0*(1.0-cL)*3
    elif cR<1.0: cent=4.0*(1.0-cR)*3
    hdes=cl(1.0*phid+cent,-38,38)
    look=-41.0
    ph=t%3.0
    if ph>=1.8 and ph<2.4: look=53.0
    elif ph>=2.4: look=-72.0
    if phase=='rev' and abs(hitch)>55:
        phase='fwd'; wk('fwd%d'%int(t),'hitch too big, pulling forward')
    if phase=='fwd':
        if abs(hitch)<10: phase='rev'
        return (0.0,1.2,look)
    steer=cl(1.8*(hitch-hdes),-42,42)
    spd=-1.4
    tg=obs.get('target') or {}
    if min(f0,best)<6 or min(cL,cR)<0.5: spd=-0.7
    if tg.get('in_sight') and tg.get('dist_m',99)<12: spd=-0.7
    if best<1.0:
        spd=0.0; wk('blocked%d'%int(t/10),'no free path behind, stopped')
    if int(t*10)%30==0:
        print('t%.0f h%.0f hd%.0f phid%.0f cent%.0f f0%.1f best%.1f cL%.1f cR%.1f n%d'%(t,hitch,hdes,phid,cent,f0,best,cL,cR,len(loc)))
